class Gradebook:
    def __init__(self) -> None:
        # assignment_name -> {"weight": float, "kind": str}
        self._assignments: dict[str, dict] = {}
        # student_name -> {assignment_name: grade}
        self._grades: dict[str, dict[str, float]] = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        self._assignments[name] = {"weight": float(weight), "kind": kind}

    def record(self, student: str, assignment: str, grade: float) -> None:
        if student not in self._grades:
            self._grades[student] = {}
        self._grades[student][assignment] = float(grade)

    def average(self, student: str) -> float:
        student_grades = self._grades.get(student, {})

        # Collect all assignments with effective grade (unrecorded defaults to 2.0)
        quizzes = []
        homeworks = []

        for name, info in self._assignments.items():
            grade = student_grades.get(name, 2.0)
            weight = info["weight"]
            kind = info["kind"]

            entry = {"name": name, "grade": grade, "weight": weight}
            if kind == "quiz":
                quizzes.append(entry)
            else:
                homeworks.append(entry)

        # If more than one quiz exists, drop the one with the lowest grade.
        if len(quizzes) > 1:
            # Sort by grade ascending; drop the first one
            lowest_idx = min(range(len(quizzes)), key=lambda i: quizzes[i]["grade"])
            quizzes.pop(lowest_idx)

        all_entries = homeworks + quizzes
        total_weight = sum(entry["weight"] for entry in all_entries)

        if total_weight == 0.0:
            return 0.0

        weighted_sum = sum(entry["grade"] * entry["weight"] for entry in all_entries)
        return round(weighted_sum / total_weight, 2)
